INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (1,1,'Acknowledged - work has started','Thanks for raising this. I have picked up your ticket and started looking into it. I will post an update here as soon as I know more, and you will get a notification when I do. You do not need to call or follow up; everything about this ticket will appear on this page.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (2,1,'Need more information','Thanks for reporting this. Before I can get much further I need a bit more detail:\n\n1. What exactly were you doing when the problem happened?\n2. What is the exact error message, word for word?\n3. Does it happen every time, or only sometimes?\n4. Has anything changed on your machine recently, such as an update or a new program?\n\nReply here with whatever you can and I will carry on from there.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (3,1,'Need a screenshot','Could you send a screenshot of what you are seeing? Press the Windows key together with Shift and S, drag a box around the error, then paste it into a reply here or attach it to the ticket.\n\nA picture of the actual message usually saves a round of back and forth.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (4,1,'Please confirm it still happens','I have not been able to reproduce this on my side. Could you try once more and tell me whether it still happens?\n\nIf it does, please note the time you tried, so I can match it against the logs.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (5,1,'Checking with the rest of the team','I have seen this before but I want to check with the rest of the team before I change anything on your machine. I will come back to you on this ticket once I have an answer.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (6,1,'Desk visit scheduled','This one needs me at your desk rather than remote. I will come by during office hours and will confirm the time here first.\n\nIf you are going to be away from your desk, reply and let me know when suits you better.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (7,1,'Please bring the device to IT','I need the device in front of me to fix this properly. Please drop it at the IT office when it suits you, and bring the charger and any cables that came with it.\n\nIf you need a loan device while I work on it, say so here and I will arrange one.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (8,1,'Replacement part ordered','I have ordered a replacement part. It normally takes three working days to arrive. I will book a time with you to fit it as soon as it is here, and this ticket stays open until the work is done.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (9,1,'Waiting on a supplier','This is now with our supplier and I am waiting on them. There is nothing further you need to do.\n\nI will update this ticket as soon as they come back to me. If you have not heard anything in a week, reply here and I will chase them.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (10,1,'Work will happen outside office hours','This change affects other people, so I will do it outside office hours to avoid disrupting anyone. Please leave your machine switched on and signed out when you leave.\n\nI will confirm here once it is done.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (11,1,'Needs manager approval','IT cannot action this one without your line manager approving it first. Please forward this ticket number to them and ask them to reply here confirming.\n\nOnce that approval is on the ticket I will carry on.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (12,1,'Moved to another department','This request belongs with another team, so I have moved it to them. The ticket number stays the same and you will keep getting updates here.\n\nNothing further is needed from you right now.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (13,1,'Outside IT scope','This one sits outside what IT handles. I have left the ticket open with a note so there is a record of the request, but the right people to action it are the team named above.\n\nIf you think this is wrong, reply here and I will take another look.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (14,1,'Password reset','I have reset your password. You will be asked to choose a new one the first time you sign in, so the temporary password only works once.\n\nRemember you can sign in with either your email address or your staff ID. Let me know if you still cannot get in.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (15,1,'Account unlocked','Your account was locked after several failed sign-in attempts. I have unlocked it and you should be able to sign in now.\n\nThe lock is automatic and clears itself after 15 minutes, so if it happens again you can simply wait rather than raising a ticket.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (16,1,'Software installed','The software is installed and ready on your machine. Please restart before you use it for the first time.\n\nIf it asks for a licence key or will not open, reply here rather than raising a new ticket, and I will sort it out.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (17,1,'Network issue fixed - please retest','I have made a change at the network end. Please disconnect and reconnect, then try again.\n\nIf it is still not working, tell me roughly what time you tested so I can line it up against the logs.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (18,1,'Printer cleared','The printer has been cleared and I have sent a test page through successfully. Please try your job again.\n\nIf it jams in the same place a third time the roller is probably worn, so raise a ticket and I will book a service.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (19,1,'Answered in the knowledge base','There is an article in the Knowledge Base that covers this, and it will get you a fix faster next time than waiting on a ticket. Open Knowledge Base from the sidebar and search for the keyword in your ticket title.\n\nI will leave this ticket open for now. Reply here if the article does not solve it.','2026-11-10 16:53:52');
INSERT INTO `canned_responses` (`id`, `created_by`, `title`, `body`, `created_at`) VALUES (20,1,'Resolved - please confirm','I believe this is now fixed. Please try again and let me know how you get on.\n\nIf I do not hear back within two working days I will close the ticket. You can always reopen it by replying here.','2026-11-10 16:53:52');
INSERT INTO `notifications` (`id`, `user_id`, `ticket_id`, `message`, `is_read`, `created_at`) VALUES (1,3,1,'Ticket #1 has a new update from the IT team',0,'2026-11-10 11:53:53');
