INSERT INTO `notifications` (`id`, `user_id`, `ticket_id`, `message`, `is_read`, `created_at`) VALUES (3,3,3,'Ticket #3 has a new update from the IT team',1,'2026-11-10 08:53:53');
INSERT INTO `notifications` (`id`, `user_id`, `ticket_id`, `message`, `is_read`, `created_at`) VALUES (4,3,4,'Ticket #4 has a new update from the IT team',1,'2026-11-10 07:23:53');
